script:
const root = root_element;
const setText = (field, value) => {
  root.querySelectorAll(`[data-field="${field}"]`).forEach((el) => {
    el.textContent = value;
  });
};

const render = (d) => {
  setText("present_today", d.present_today ?? 0);
  setText("presence_rate", d.presence_rate ?? 0);
  setText("complete_today", d.complete_today ?? 0);
  setText("complete_rate", d.complete_rate ?? 0);
  setText("avg_hours", Number(d.avg_hours || 0).toFixed(2));
  setText("still_in", d.still_in ?? 0);

  const chart = root.querySelector("[data-bars]");
  if (!chart) return;
  chart.innerHTML = "";

  const labels = d.week_labels || [];
  const ins = d.week_ins || [];
  const outs = d.week_outs || [];
  const max = Math.max(
    1,
    ...ins.map(Number),
    ...outs.map(Number)
  );

  labels.forEach((label, i) => {
    const inVal = Number(ins[i] || 0);
    const outVal = Number(outs[i] || 0);
    const inH = inVal ? Math.max(8, (inVal / max) * 100) : 3;
    const outH = outVal ? Math.max(8, (outVal / max) * 100) : 3;
    const day = document.createElement("div");
    day.className = "etp-an__day";
    day.innerHTML = `
      <div class="etp-an__day-vals">
        <span class="in">${inVal || ""}</span>
        <span class="out">${outVal || ""}</span>
      </div>
      <div class="etp-an__pair">
        <div class="etp-an__bar etp-an__bar--in${inVal ? "" : " is-empty"}" style="height:${inH}%"></div>
        <div class="etp-an__bar etp-an__bar--out${outVal ? "" : " is-empty"}" style="height:${outH}%"></div>
      </div>
      <div class="etp-an__day-label">${frappe.utils.escape_html(label)}</div>
    `;
    chart.appendChild(day);
  });
};

frappe.call({
  method: "easytimepro.easy_timepro.analytics.get_workspace_kpis",
  callback(r) {
    if (r.message) render(r.message);
  },
});

style:
.etp-an {
  font-family: inherit;
  color: #101828;
}
.etp-an__kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  background: #e4e7ec;
  border: 1px solid #e4e7ec;
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 16px;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}
.etp-an__kpi {
  background: #ffffff;
  padding: 22px 24px 20px;
  min-height: 118px;
}
.etp-an__label {
  font-size: 12px;
  font-weight: 600;
  color: #667085;
  margin-bottom: 10px;
}
.etp-an__value {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
  color: #101828;
  font-variant-numeric: tabular-nums;
}
.etp-an__unit {
  font-size: 16px;
  font-weight: 600;
  color: #98a2b3;
  margin-left: 2px;
}
.etp-an__hint {
  margin-top: 10px;
  font-size: 12px;
  color: #98a2b3;
  line-height: 1.35;
}
.etp-an__trend {
  background: #ffffff;
  border: 1px solid #e4e7ec;
  border-radius: 12px;
  padding: 20px 24px 18px;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}
.etp-an__trend-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.etp-an__trend-title {
  font-size: 14px;
  font-weight: 650;
  color: #101828;
}
.etp-an__legend {
  display: flex;
  gap: 14px;
  font-size: 12px;
  color: #667085;
}
.etp-an__legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.etp-an__dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  display: inline-block;
}
.etp-an__dot--in { background: #1f4b99; }
.etp-an__dot--out { background: #b42318; }
.etp-an__chart {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
  min-height: 130px;
}
.etp-an__day {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.etp-an__pair {
  width: 100%;
  max-width: 40px;
  height: 100px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
}
.etp-an__bar {
  flex: 1;
  min-height: 3px;
  border-radius: 5px 5px 2px 2px;
  transition: height 0.45s ease;
}
.etp-an__bar--in { background: #1f4b99; }
.etp-an__bar--out { background: #b42318; }
.etp-an__bar.is-empty {
  background: #e4e7ec;
  height: 3px !important;
}
.etp-an__day-vals {
  display: flex;
  gap: 6px;
  font-size: 10px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  color: #667085;
  min-height: 14px;
}
.etp-an__day-vals .in { color: #1f4b99; }
.etp-an__day-vals .out { color: #b42318; }
.etp-an__day-label {
  font-size: 11px;
  color: #98a2b3;
  font-weight: 500;
}
@media (max-width: 900px) {
  .etp-an__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 560px) {
  .etp-an__kpis { grid-template-columns: 1fr; }
  .etp-an__chart { gap: 6px; }
}
